lp-keyframes.code:
/* One loop on the demo dot: move on --curve, hold, then reset to 0%.
   Each keyframe's animation-timing-function governs the segment that starts there.
   Period 2400ms: move is 0 to 40% (960ms), hold is 40% to 100% (1440ms). */
.demo-dot {
  --travel: 240px;
  animation: lp-loop 2400ms infinite;
}
@keyframes lp-loop {
  0%   { transform: translateX(0);             animation-timing-function: var(--curve); }
  40%  { transform: translateX(var(--travel)); animation-timing-function: linear; }
  100% { transform: translateX(var(--travel)); }
}
/* Reduced motion: no loop; show the rest state. */
@media (prefers-reduced-motion: reduce) {
  .demo-dot { animation: none; transform: translateX(var(--travel)); }
}
